"""Version 2 schema. MySQL is production; SQLite is an explicit test backend."""
from sqlalchemy import (MetaData, Table, Column as C, BigInteger as ID, Integer, String,
                        Text, Double as Float, Boolean, Index, UniqueConstraint)

metadata = MetaData()
def table(name, *columns, **kw):
    return Table(name, metadata, *columns, mysql_engine='InnoDB', mysql_charset='utf8mb4', mysql_collate='utf8mb4_bin', **kw)
def pk(): return C('id', ID, primary_key=True, autoincrement=False)
def stamp(): return C('created_at', Float, nullable=False)
users = table('users', pk(), C('auth_subject', String(190), unique=True, nullable=False), C('status', String(20)), stamp())
workspaces = table('workspaces', pk(), C('owner_id', ID, nullable=False), C('name', String(120)), C('snapshot_ref', String(255)), C('version', Integer, nullable=False), stamp(), Index('ix_workspace_owner', 'owner_id', 'id'))
members = table('workspace_members', C('workspace_id', ID, primary_key=True), C('user_id', ID, primary_key=True), C('role', String(20)), Index('ix_member_user', 'user_id', 'workspace_id'))
sessions = table('agent_sessions', pk(), C('user_id', ID, nullable=False), C('workspace_id', ID, nullable=False), C('title', String(120)), C('status', String(20)), C('active_run_id', ID), C('next_seq', ID, nullable=False), C('version', Integer, nullable=False), C('updated_at', Float, nullable=False), stamp(), Index('ix_session_user_page', 'user_id', 'updated_at', 'id'), Index('ix_session_workspace_page', 'workspace_id', 'updated_at', 'id'))
runs = table('agent_runs', pk(), C('input_protocol_version', Integer, server_default='1'), C('user_id', ID, nullable=False), C('workspace_id', ID, nullable=False), C('session_id', ID, nullable=False), C('status', String(24), nullable=False), C('idempotency_key', String(100), nullable=False), C('request_hash', String(64), nullable=False), C('input_ref', String(255), nullable=False), C('resumed_from_run_id', ID), C('worker_id', String(80)), C('lease_until', Float), C('fence_token', Integer, nullable=False), C('deadline_at', Float), C('queue_deadline', Float, nullable=False), C('next_dispatch_at', Float, nullable=False), C('cancel_requested_at', Float), C('stop_reason', String(80)), C('error_code', String(80)), C('checkpoint_ref', String(255)), C('workspace_version', Integer, nullable=False), C('event_seq', Integer, nullable=False), C('output_bytes', ID, nullable=False), C('started_at', Float), C('finished_at', Float), C('trace_ref', String(255)), stamp(), UniqueConstraint('user_id','idempotency_key',name='uq_run_idempotency'), Index('ix_run_session','session_id','id'), Index('ix_run_dispatch','status','next_dispatch_at','id'), Index('ix_run_lease','status','lease_until','id'), Index('ix_run_user_state','user_id','status','id'))
messages = table('messages', pk(), C('user_id', ID, nullable=False), C('session_id', ID, nullable=False), C('run_id', ID, nullable=False), C('seq', ID, nullable=False), C('role', String(20)), C('content_preview', Text), C('content_ref', String(255)), C('content_bytes', ID), C('is_partial', Boolean), stamp(), UniqueConstraint('session_id','seq',name='uq_message_seq'), Index('ix_message_run','run_id','id'))
tools = table('tool_calls', pk(), C('executor_protocol_version', Integer, server_default='1'), C('user_id', ID, nullable=False), C('session_id', ID, nullable=False), C('run_id', ID, nullable=False), C('seq', ID, nullable=False), C('tool_name', String(80)), C('args_preview', Text), C('args_ref', String(255)), C('status', String(24)), C('deadline_at', Float), C('sandbox_id', String(100)), C('exit_code', Integer), C('term_signal', Integer), C('stdout_preview', Text), C('stderr_preview', Text), C('output_ref', String(255)), C('output_bytes', ID), C('truncated', Boolean), C('cached', Boolean), C('started_at', Float), C('finished_at', Float), C('side_effect_key', String(100)), C('error_code', String(80)), stamp(), UniqueConstraint('session_id','seq',name='uq_tool_seq'), UniqueConstraint('user_id','side_effect_key',name='uq_tool_effect'), Index('ix_tool_run','run_id','id'))
records = table('session_records', C('session_id', ID, primary_key=True), C('seq', ID, primary_key=True), C('record_type', String(20)), C('record_id', ID, nullable=False))
approvals = table('approvals', pk(), C('user_id', ID, nullable=False), C('workspace_id', ID), C('session_id', ID), C('run_id', ID), C('confirmation_id', String(100)), C('action_name', String(80)), C('args_hash', String(64)), C('status', String(24)), C('expires_at', Float), C('decided_by', ID), C('consumed_at', Float), stamp(), Index('ix_approval_run','run_id','status','id'), Index('ix_approval_expiry','status','expires_at','id'))
memories = table('memories', pk(), C('user_id', ID), C('workspace_id', ID), C('session_id', ID), C('kind', String(30)), C('summary', Text), C('content_ref', String(255)), C('source_record_id', ID), C('version', Integer), stamp(), Index('ix_memory_scope','user_id','workspace_id','kind','id'), Index('ix_memory_session','session_id','id'))
audit = table('audit_logs', pk(), C('workspace_id', ID), C('actor_id', ID), C('session_id', ID), C('run_id', ID), C('action', String(80)), C('result', String(80)), stamp(), Index('ix_audit_workspace','workspace_id','created_at','id'), Index('ix_audit_run','run_id','id'))
events = table('run_events', C('run_id', ID, primary_key=True), C('event_seq', Integer, primary_key=True), C('type', String(40)), C('payload_preview', Text), stamp())
outbox = table('outbox', pk(), C('run_id', ID), C('published_at', Float), C('attempts', Integer, nullable=False), C('next_attempt_at', Float, nullable=False), stamp(), Index('ix_outbox_pending','published_at','next_attempt_at','id'))
capacity = table('runtime_capacity', C('scope', String(100), primary_key=True), C('last_dispatch_at', Float, nullable=False))
pending = table('pending_decisions', C('key', String(160), primary_key=True), C('payload', Text), C('expires_at', Float))
versions = table('schema_versions', C('version', Integer, primary_key=True), stamp())
